CREATE OR REPLACE FUNCTION public.ranked_questions(course_ids uuid[] DEFAULT NULL,campus_id uuid DEFAULT NULL,community uuid DEFAULT NULL,search_text text DEFAULT '',sort_mode text DEFAULT 'hot') RETURNS SETOF public.questions LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT q.* FROM public.questions q WHERE (course_ids IS NULL OR q.course_id=ANY(course_ids)) AND (campus_id IS NULL OR q.institution_id=campus_id) AND (community IS NULL OR EXISTS(SELECT 1 FROM public.question_communities t WHERE t.question_id=q.id AND t.community_id=community)) AND (search_text='' OR q.title ILIKE '%'||search_text||'%') ORDER BY CASE WHEN sort_mode='new' THEN extract(epoch FROM q.created_at) WHEN sort_mode='top' THEN (SELECT count(*) FROM public.question_votes v WHERE v.question_id=q.id) ELSE ((SELECT count(*) FROM public.question_votes v WHERE v.question_id=q.id)+q.answer_count*2+(SELECT count(DISTINCT a.author_id) FROM public.answers a WHERE a.question_id=q.id)*3+1)/power(GREATEST(extract(epoch FROM (now()-q.created_at))/3600,0)+2,1.25) END DESC,q.created_at DESC LIMIT 100 $$;
GRANT EXECUTE ON FUNCTION public.ranked_questions(uuid[],uuid,uuid,text,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.community_activity() RETURNS TABLE(id uuid,name text,slug text,description text,institution_id uuid,members bigint,posts bigint,participants bigint,activity numeric) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT c.id,c.name,c.slug,c.description,c.institution_id,(SELECT count(*) FROM public.community_members m WHERE m.community_id=c.id),(SELECT count(*) FROM public.question_communities t WHERE t.community_id=c.id),(SELECT count(DISTINCT a.author_id) FROM public.answers a JOIN public.question_communities t ON t.question_id=a.question_id WHERE t.community_id=c.id AND a.created_at>now()-interval '7 days'),((SELECT count(*) FROM public.question_votes v JOIN public.question_communities t ON t.question_id=v.question_id WHERE t.community_id=c.id AND v.created_at>now()-interval '7 days')+(SELECT count(*)*2 FROM public.answers a JOIN public.question_communities t ON t.question_id=a.question_id WHERE t.community_id=c.id AND a.created_at>now()-interval '7 days')+(SELECT count(*) FROM public.question_communities t JOIN public.questions q ON q.id=t.question_id WHERE t.community_id=c.id AND q.created_at>now()-interval '7 days'))::numeric FROM public.communities c ORDER BY 9 DESC,6 DESC $$;
GRANT EXECUTE ON FUNCTION public.community_activity() TO anon,authenticated;